   0 /**
   1  * Flow Configuration Service
   2  * 
   3  * CRUD operations for flow configurations stored in Firestore.
   4  * Handles flow creation, updates, versioning, and retrieval.
   5  */
   6 
   7 import { 
   8   collection, 
   9   doc, 
  10   getDoc, 
  11   getDocs, 
  12   setDoc, 
  13   updateDoc, 
  14   deleteDoc, 
  15   query, 
  16   where, 
