  32 /**
  33  * Flow Configuration Service Class
  34  */
  35 export class FlowConfigService {
  36   private readonly flowsCollection = collection(db, FLOW_COLLECTIONS.CONFIGURATIONS);
  37   private readonly versionsCollection = collection(db, FLOW_COLLECTIONS.VERSIONS);
  38 
  39   /**
  40    * Get flow configuration by name
  41    */
  42   async getFlowByName(flowName: string): Promise<FlowConfiguration | null> {
  43     try {
  44       const q = query(
  45         this.flowsCollection,
  46         where('name', '==', flowName),
  47         where('status', '==', 'active'),
  48         limit(1)
  49       );
  50       
  51       const snapshot = await getDocs(q);
  52       
  53       if (snapshot.empty) {
  54         return null;
  55       }
  56       
  57       const docData = snapshot.docs[0].data();
  58       return this.mapToFlowConfiguration(snapshot.docs[0].id, docData);
  59     } catch (error) {
  60       console.error('Error getting flow by name:', error);
  61       throw new FlowServiceError('Failed to get flow by name', error);
  62     }
  63   }
  64 
  65   /**
  66    * Get flow configuration by ID
  67    */
  68   async getFlowById(flowId: string): Promise<FlowConfiguration | null> {
  69     try {
  70       const docRef = doc(this.flowsCollection, flowId);
  71       const docSnap = await getDoc(docRef);
  72       
  73       if (!docSnap.exists()) {
  74         return null;
  75       }
  76       
  77       return this.mapToFlowConfiguration(docSnap.id, docSnap.data());
  78     } catch (error) {
  79       console.error('Error getting flow by ID:', error);
  80       throw new FlowServiceError('Failed to get flow by ID', error);
  81     }
  82   }
  83 
  84   /**
  85    * List all flows with optional filters
  86    */
  87   async listFlows(filters?: FlowFilters): Promise<FlowConfiguration[]> {
  88     try {
  89       const constraints: QueryConstraint[] = [];
  90       
  91       if (filters?.status) {
  92         constraints.push(where('status', '==', filters.status));
  93       }
  94       
  95       if (filters?.category) {
  96         constraints.push(where('category', '==', filters.category));
  97       }
  98       
  99       if (filters?.tags && filters.tags.length > 0) {
 100         constraints.push(where('tags', 'array-contains-any', filters.tags));
 101       }
 102       
 103       // Order by creation date (most recent first)
 104       constraints.push(orderBy('createdAt', 'desc'));
 105       
 106       if (filters?.limit) {
 107         constraints.push(limit(filters.limit));
 108       }
 109       
 110       const q = query(this.flowsCollection, ...constraints);
 111       const snapshot = await getDocs(q);
 112       
 113       return snapshot.docs.map(doc => 
 114         this.mapToFlowConfiguration(doc.id, doc.data())
 115       );
 116     } catch (error) {
 117       console.error('Error listing flows:', error);
 118       throw new FlowServiceError('Failed to list flows', error);
 119     }
 120   }
