 122   /**
 123    * Create a new flow configuration
 124    */
 125   async createFlow(
 126     flow: Partial<FlowConfiguration>,
 127     userId: string
 128   ): Promise<FlowConfiguration> {
 129     try {
 130       // Validate flow configuration
 131       const errors = validateFlowConfiguration(flow);
 132       if (errors.length > 0) {
 133         throw new ValidationError('Flow validation failed', errors);
 134       }
 135       
 136       // Check if flow with same name already exists
 137       const existing = await this.getFlowByName(flow.name!);
 138       if (existing) {
 139         throw new FlowAlreadyExistsError(flow.name!);
 140       }
 141       
 142       // Create flow configuration with defaults
 143       const flowConfig = createFlowConfiguration({
 144         ...flow,
 145         createdBy: userId,
 146       });
 147       
 148       // Create new document
 149       const docRef = doc(this.flowsCollection);
 150       const now = Timestamp.now();
 151       
 152       const flowData: FlowConfiguration = {
 153         ...flowConfig,
 154         id: docRef.id,
 155         createdAt: now,
 156         updatedAt: now,
 157       } as FlowConfiguration;
 158       
 159       await setDoc(docRef, this.flowToFirestore(flowData));
 160       
 161       // Create initial version
 162       await this.createVersion(flowData, userId, 'Initial version');
 163       
 164       return flowData;
 165     } catch (error) {
 166       console.error('Error creating flow:', error);
 167       if (error instanceof FlowServiceError) {
 168         throw error;
 169       }
 170       throw new FlowServiceError('Failed to create flow', error);
 171     }
 172   }
 173 
 174   /**
 175    * Update flow configuration
 176    */
 177   async updateFlow(
 178     flowId: string,
 179     updates: Partial<FlowConfiguration>,
 180     userId: string,
 181     versionMessage?: string
 182   ): Promise<FlowConfiguration> {
 183     try {
 184       const docRef = doc(this.flowsCollection, flowId);
 185       const existing = await this.getFlowById(flowId);
 186       
 187       if (!existing) {
 188         throw new FlowNotFoundError(flowId);
 189       }
 190       
 191       // Validate updated configuration (pass isUpdate flag)
 192       const updatedFlow = { ...existing, ...updates };
 193       const errors = validateFlowConfiguration(updatedFlow, true);
 194       if (errors.length > 0) {
 195         throw new ValidationError('Flow validation failed', errors);
 196       }
 197       
 198       // Increment version
 199       const newVersion = existing.version + 1;
 200       
 201       const updateData = {
 202         ...updates,
 203         version: newVersion,
 204         updatedAt: Timestamp.now(),
 205       };
 206       
 207       await updateDoc(docRef, this.flowToFirestore(updateData));
 208       
 209       // Create version snapshot
 210       const updatedFlowConfig = { ...existing, ...updateData };
 211       await this.createVersion(updatedFlowConfig, userId, versionMessage);
 212       
 213       return updatedFlowConfig;
 214     } catch (error) {
 215       console.error('Error updating flow:', error);
 216       if (error instanceof FlowServiceError) {
 217         throw error;
 218       }
 219       throw new FlowServiceError('Failed to update flow', error);
 220     }
 221   }
 222 
 223   /**
 224    * Update flow status
 225    */
 226   async updateFlowStatus(
 227     flowId: string,
 228     status: FlowStatus,
 229     userId: string
 230   ): Promise<void> {
 231     try {
 232       const docRef = doc(this.flowsCollection, flowId);
 233       const existing = await this.getFlowById(flowId);
 234       
 235       if (!existing) {
 236         throw new FlowNotFoundError(flowId);
 237       }
 238       
 239       const updateData: any = {
 240         status,
 241         updatedAt: Timestamp.now(),
 242       };
 243       
 244       if (status === 'active' && !existing.publishedAt) {
 245         updateData.publishedAt = Timestamp.now();
 246       }
 247       
 248       await updateDoc(docRef, updateData);
 249       
 250       // Create version snapshot for status change
 251       await this.createVersion(
 252         { ...existing, status },
 253         userId,
 254         `Status changed to ${status}`
 255       );
 256     } catch (error) {
 257       console.error('Error updating flow status:', error);
 258       if (error instanceof FlowServiceError) {
 259         throw error;
 260       }
 261       throw new FlowServiceError('Failed to update flow status', error);
 262     }
 263   }
 264 
 265   /**
 266    * Delete flow configuration
 267    */
 268   async deleteFlow(flowId: string): Promise<void> {
 269     try {
 270       const docRef = doc(this.flowsCollection, flowId);
 271       const existing = await this.getFlowById(flowId);
 272       
 273       if (!existing) {
 274         throw new FlowNotFoundError(flowId);
 275       }
 276       
 277       // Soft delete by setting status to archived
 278       await this.updateFlowStatus(flowId, 'archived', 'system');
 279       
