  try {
    // Check initialization status
    const initStatus = getFirebaseInitStatus();

    if (!isFirebaseInitialized()) {
      return NextResponse.json({
        success: false,
        error: 'Firebase not fully initialized',
        status: initStatus,
        hint: 'Check NEXT_PUBLIC_FIREBASE_* environment variables in .env.local',
        requiredVars: [
          'NEXT_PUBLIC_FIREBASE_API_KEY',
          'NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN',
          'NEXT_PUBLIC_FIREBASE_PROJECT_ID',
          'NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET',
          'NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID',
          'NEXT_PUBLIC_FIREBASE_APP_ID',
        ]
      }, { status: 500 });
    }

    // Test Firestore connection by importing the service
    const { flowConfigService } = await import('@/services/flow-config-service');

    // Try to list flows (with limit 1 for quick test)
    const flows = await flowConfigService.listFlows({ limit: 1 });

    return NextResponse.json({
      success: true,
      message: '✅ Firebase connection successful!',
      details: {
        initialized: true,
        flowsFound: flows.length,
        canAccessFirestore: true,
      },
      status: initStatus,
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('Firebase test error:', error);

